import * as nodeFs from 'node:fs';
import * as nodeCrypto from 'node:crypto';
import * as nodePath from 'node:path';

// Chosen numbers (see answer): send window 08:00 to 21:00 recipient-local,
// 1 per type per local day, 3 notifications of any type per local day,
// after a dismissal the type pauses min(2^n, 14) days (n = dismissals so far).
const SEND_START = '08:00';
const SEND_END = '21:00';
const PER_TYPE_PER_DAY = 1;
const ALL_TYPES_PER_DAY = 3;
const MAX_PAUSE_DAYS = 14;
const DAY_MS = 86400000;
const CONSENT_PURPOSE = 'marketing';

function stateDir() {
  const dir = process.env.STATE_DIR || nodePath.join(process.cwd(), '.gate-state');
  nodeFs.mkdirSync(dir, { recursive: true });
  return dir;
}
function h(prefix, ...parts) {
  const hash = nodeCrypto.createHash('sha256').update(JSON.stringify(parts)).digest('hex').slice(0, 40);
  return `${prefix}_${hash}`;
}
function pickZone(user) {
  for (const z of [user.deviceTimezone, user.timezone]) {
    if (typeof z === 'string' && z && z !== 'UTC' && gkZoneOk(z)) return z;
  }
  return null;
}
const no = (reason, extra = {}) => ({ send: false, reason, ...extra });

export async function decide({ user, candidate, now, flags } = {}) {
  if (!user || typeof user.id !== 'string' || !user.id || !candidate || !candidate.id || !candidate.type || !(now instanceof Date) || isNaN(now)) {
    return no('The notification was held because the request data is incomplete.');
  }
  if (!flags || flags.proactiveEnabled !== true) {
    return no('Proactive notifications are switched off by operations right now.');
  }
  const dir = stateDir();
  const ms = now.getTime();
  const type = String(candidate.type);

  // Opt-out beats everything else.
  if (gkRead(dir, h('optout', user.id, type))) {
    return no(`The user switched off ${type} notifications, so none are sent.`);
  }
  // Consent: absent or false means off.
  if (!user.consents || user.consents[CONSENT_PURPOSE] !== true) {
    return no(`The user has not given ${CONSENT_PURPOSE} consent, so no ${type} notification is sent.`);
  }
  // Same message id already delivered: same answer, nothing spent twice.
  const sentKey = h('sent', user.id, candidate.id);
  if (gkRead(dir, sentKey)) return { send: true, reason: null };

  const zone = pickZone(user);
  if (!zone) {
    return no('The recipient time zone is missing or invalid, so the local time is unknown and the notification is held.');
  }
  if (!gkInWindow(ms, zone, SEND_START, SEND_END)) {
    const next = gkNextOpen(ms, zone, SEND_START, SEND_END);
    return no(`Quiet hours: notifications go out only from ${SEND_START} to ${SEND_END} recipient-local time. Next chance: ${gkFmt(next, zone)}.`, { nextAllowedAt: new Date(next) });
  }
  // Pause after dismissals.
  const dis = gkRead(dir, h('dislast', user.id, type));
  if (dis && typeof dis.n === 'number' && typeof dis.at === 'number') {
    const until = dis.at + Math.min(2 ** dis.n, MAX_PAUSE_DAYS) * DAY_MS;
    if (ms < until) {
      const next = gkInWindow(until, zone, SEND_START, SEND_END) ? until : gkNextOpen(until, zone, SEND_START, SEND_END);
      return no(`The user dismissed a ${type} notification recently, so it is paused until ${gkFmt(next, zone)}.`, { nextAllowedAt: new Date(next) });
    }
  }

  // Claim the id, then spend the caps. Give back everything on refusal.
  const claimKey = h('claim', user.id, candidate.id);
  if (!gkClaim(dir, claimKey)) {
    if (gkRead(dir, sentKey)) return { send: true, reason: null };
    return no('This notification id is already being handled by another worker.');
  }
  const day = gkDayKey(ms, zone);
  const typeKey = h('captype', user.id, type, day);
  const allKey = h('capall', user.id, day);
  let typeSpent = false;
  try {
    const t = gkCount(dir, typeKey, PER_TYPE_PER_DAY);
    if (!t.ok) {
      gkUnclaim(dir, claimKey);
      const next = gkNextOpen(gkNextMidnight(ms, zone), zone, SEND_START, SEND_END);
      return no(`Daily limit: only ${PER_TYPE_PER_DAY} ${type} notification per day. Next chance: ${gkFmt(next, zone)}.`, { nextAllowedAt: new Date(next) });
    }
    typeSpent = true;
    const a = gkCount(dir, allKey, ALL_TYPES_PER_DAY);
    if (!a.ok) {
      gkRefund(dir, typeKey);
      gkUnclaim(dir, claimKey);
      const next = gkNextOpen(gkNextMidnight(ms, zone), zone, SEND_START, SEND_END);
      return no(`Daily limit: at most ${ALL_TYPES_PER_DAY} notifications per day. Next chance: ${gkFmt(next, zone)}.`, { nextAllowedAt: new Date(next) });
    }
    gkWrite(dir, sentKey, { at: ms, type });
    return { send: true, reason: null };
  } catch (e) {
    if (typeSpent) { try { gkRefund(dir, typeKey); } catch {} }
    try { gkUnclaim(dir, claimKey); } catch {}
    return no('The notification was held because of an internal error.');
  }
}

export async function recordDismissal(userId, type, now) {
  const dir = stateDir();
  const at = now instanceof Date && !isNaN(now) ? now.getTime() : Date.now();
  const c = gkCount(dir, h('discount', userId, type), 1e9);
  gkWrite(dir, h('dislast', userId, type), { n: c.n, at });
}

export async function optOut(userId, type) {
  gkWrite(stateDir(), h('optout', userId, type), { at: Date.now() });
}
EOF
