const f = { proactiveEnabled:true };
const noon = new Date('2026-10-23T16:00:00Z'), D = 86400000;
if (process.argv[2]) { // worker: same user, distinct ids
  const r = await decide({user:u('p'),candidate:{id:'w'+process.argv[2],type:'checkin'},now:noon,flags:f});
  console.log(r.send); process.exit(0);
}
await recordDismissal('h','checkin',noon);
let r = await decide({user:u('h'),candidate:{id:'z1',type:'checkin'},now:new Date(noon.getTime()+D),flags:f}); assert(!r.send); console.log(r.reason);
r = await decide({user:u('h'),candidate:{id:'z2',type:'checkin'},now:new Date(noon.getTime()+3*D),flags:f}); assert(r.send);
